'use client'

// Generated by SpecForge from "Shop" (1.0.0). Safe to edit.
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { useApi } from '@/lib/api/api-provider'
import type { Page } from '@/lib/api/types'
import type { Order, OrderInput } from './types'

const PATH = '/api/shop/orders'
const KEY = ['shop', 'order'] as const

export interface OrderFilters {
  q?: string
  page?: number
  size?: number
  sort?: string
}

const item = (id: number) => `${PATH}/${encodeURIComponent(String(id))}`

export function useOrderList(filters: OrderFilters) {
  const api = useApi()
  return useQuery({
    queryKey: [...KEY, filters],
    queryFn: () => api.get<Page<Order>>(PATH, { ...filters }),
    placeholderData: previous => previous,
  })
}

export function useSaveOrder() {
  const api = useApi()
  const queryClient = useQueryClient()
  return useMutation({
    mutationFn: ({ id, input }: { id?: number; input: OrderInput }) =>
      id != null ? api.put<Order>(item(id), input) : api.post<Order>(PATH, input),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ['shop'] }),
  })
}

export function useDeleteOrder() {
  const api = useApi()
  const queryClient = useQueryClient()
  return useMutation({
    mutationFn: (id: number) => api.delete(item(id)),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ['shop'] }),
  })
}
